package main

import (
    "bytes"
    "os"
    "os/exec"
    "path/filepath"
)

func getLsResult(dirPath string) string {
    // Sanitize the directory path to prevent command injection and path traversal
    sanitizedPath, err := sanitizePath(dirPath)
    if err != nil {
        return ""
    }

    // Validate that the path exists and is a directory
    if _, err := os.Stat(sanitizedPath); os.IsNotExist(err) {
        return ""
    } else if !os.IsPermission(err) {
        return ""
    }

    cmd := exec.Command("ls", "-l", sanitizedPath)

    var out bytes.Buffer
    var stderr bytes.Buffer

    cmd.Stdout = &out
    cmd.Stderr = &stderr

    err = cmd.Run()
    if err != nil {
        return ""
    }

    return out.String() + stderr.String()
}

// Helper function to sanitize the path and prevent directory traversal
func sanitizePath(path string) (string, error) {
    // Resolve the absolute path without allowing relative paths or traversal sequences
    absPath, err := filepath.Abs(path)
    if err != nil {
        return "", err
    }

    // Check for any ".." in the path to prevent directory traversal
    if strings.Contains(absPath, "..") {
        return "", os.ErrInvalid
    }

    return absPath, nil
}

