package main

import (
    "os"
    "path/filepath"
)

func sanitizeAndValidatePath(dirPath string) (string, error) {
    // Sanitize the path by cleaning it
    sanitizedPath := filepath.Clean(dirPath)

    // Check if the path exists and is a directory
    _, err := os.Stat(sanitizedPath)
    if err != nil {
        return "", err
    }

    return sanitizedPath, nil
}
